insert into regions (id, display_order, status, is_example, dataset_version, name, summary, center_lat_deg, center_lon_east_deg, center_approximate, thumbnail_url, frame_id, frame_description, source_crs, min_x, min_y, max_x, max_y, elevation_min_m, elevation_max_m, mission_objective, route_defaults, available_layers, available_pois, available_routes, available_terrain_3d) values ('jezero-margin', 0, 'active', true, 'example-v0', '{"es":"Cráter Jezero — Margin Unit","en":"Jezero Crater — Margin Unit"}'::jsonb, '{"es":"La antigua orilla de un lago donde Perseverance halló rastros de tres sistemas de agua distintos.","en":"The ancient shoreline of a lake where Perseverance found traces of three distinct water systems."}'::jsonb, 18.38, 77.58, true, 'https://assets.example.invalid/jezero-margin/example-v0/thumbnail.webp', 'jezero-margin-local-m', '{"es":"Metros desde la esquina suroeste del recorte: x al este, y al norte, z elevación.","en":"Metres from the south-west corner of the crop: x east, y north, z elevation."}'::jsonb, null, 0.0, 0.0, 4000.0, 3000.0, -2440.0, -2273.7, '{"es":"Recorrer la Margin Unit desde la base y visitar las rocas de los tres episodios de agua, en orden.","en":"Walk the Margin Unit from the base and visit the rocks of the three water episodes, in order."}'::jsonb, '{"max_slope_deg":25.0,"eva_time_limit_min":240.0,"profiles":["shortest","fastest","safest"],"include_return":true,"soft_soil_penalty":2.0,"walking_model":"tobler-mars-v1"}'::jsonb, true, true, true, true);
insert into regions (id, display_order, status, is_example, dataset_version, name, summary, center_lat_deg, center_lon_east_deg, center_approximate, thumbnail_url, frame_id, frame_description, source_crs, min_x, min_y, max_x, max_y, elevation_min_m, elevation_max_m, mission_objective, route_defaults, available_layers, available_pois, available_routes, available_terrain_3d) values ('medusae-fossae', 1, 'preview', true, 'example-v0', '{"es":"Medusae Fossae — próxima misión","en":"Medusae Fossae — next mission"}'::jsonb, '{"es":"Depósito ecuatorial que podría guardar hielo bajo cientos de metros de polvo.","en":"Equatorial deposit that may hold ice beneath hundreds of metres of dust."}'::jsonb, -2.0, 190.0, true, 'https://assets.example.invalid/medusae-fossae/example-v0/thumbnail.webp', 'medusae-fossae-local-m', '{"es":"Sin marco local: región en modo avance.","en":"No local frame: preview region."}'::jsonb, null, null, null, null, null, null, null, '{"es":"Próxima misión: estudiar el sitio como posible fuente de agua para una base humana ecuatorial.","en":"Next mission: study the site as a possible water source for an equatorial human base."}'::jsonb, null, false, false, false, false);
insert into region_facts (region_id, ord, text, certainty) values ('jezero-margin', 0, '{"es":"La Margin Unit es roca ígnea rica en olivino, no sedimento del lago como se creía desde órbita.","en":"The Margin Unit is olivine-rich igneous rock, not lake sediment as orbital data suggested."}'::jsonb, 'confirmed');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('jezero-margin', 0, 0, 'src-34baed2a49a1');
insert into region_facts (region_id, ord, text, certainty) values ('jezero-margin', 1, '{"es":"Episodio 1: agua subterránea con CO₂ formó crestas de carbonato en las fracturas de las zonas bajas.","en":"Episode 1: CO₂-rich groundwater formed carbonate ridges in fractures at lower elevations."}'::jsonb, 'interpretation');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('jezero-margin', 1, 0, 'src-34baed2a49a1');
insert into region_facts (region_id, ord, text, certainty) values ('jezero-margin', 2, '{"es":"Episodio 2: el lago dejó sílice en las rocas que quedaron bajo la línea de agua.","en":"Episode 2: the lake left silica in rocks below the water line."}'::jsonb, 'interpretation');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('jezero-margin', 2, 0, 'src-34baed2a49a1');
insert into region_facts (region_id, ord, text, certainty) values ('jezero-margin', 3, '{"es":"Episodio 3: agua caliente dejó venas con sulfato de calcio y fluorita en la parte este.","en":"Episode 3: hot water left veins with calcium sulfate and fluorite in the eastern part."}'::jsonb, 'interpretation');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('jezero-margin', 3, 0, 'src-34baed2a49a1');
insert into region_facts (region_id, ord, text, certainty) values ('medusae-fossae', 0, '{"es":"El radar MARSIS detectó depósitos de hasta 3.7 km de espesor compatibles con capas de hielo.","en":"MARSIS radar detected deposits up to 3.7 km thick consistent with layered ice."}'::jsonb, 'interpretation');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('medusae-fossae', 0, 0, 'src-67392e082edb');
insert into region_facts (region_id, ord, text, certainty) values ('medusae-fossae', 1, '{"es":"Si fuera hielo y se fundiera, cubriría Marte con 1.5 a 2.7 m de agua.","en":"If it is ice and melted, it would cover Mars with 1.5 to 2.7 m of water."}'::jsonb, 'interpretation');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('medusae-fossae', 1, 0, 'src-67392e082edb');
insert into region_facts (region_id, ord, text, certainty) values ('medusae-fossae', 2, '{"es":"Estaría bajo una capa seca de varios cientos de metros: inaccesible por décadas.","en":"It would lie under a dry layer several hundred metres thick: out of reach for decades."}'::jsonb, 'interpretation');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('medusae-fossae', 2, 0, 'src-67392e082edb');
insert into region_facts (region_id, ord, text, certainty) values ('medusae-fossae', 3, '{"es":"Otra interpretación sostiene que es roca volcánica muy porosa, sin hielo.","en":"Another interpretation holds it is highly porous volcanic rock, without ice."}'::jsonb, 'hypothesis');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('medusae-fossae', 3, 0, 'src-da3f91aff3de');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('medusae-fossae', 3, 1, 'src-f4a6cb2e42bc');
insert into region_facts (region_id, ord, text, certainty) values ('medusae-fossae', 4, '{"es":"Es la mayor fuente individual del polvo de Marte.","en":"It is the largest single source of dust on Mars."}'::jsonb, 'confirmed');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('medusae-fossae', 4, 0, 'src-c56b1f4f56ae');
insert into region_facts (region_id, ord, text, certainty) values ('medusae-fossae', 5, '{"es":"Se formó por erupciones volcánicas explosivas hace más de 3,000 millones de años.","en":"It formed through explosive volcanic eruptions more than 3 billion years ago."}'::jsonb, 'interpretation');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('medusae-fossae', 5, 0, 'src-da3f91aff3de');
